  function formatTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;}
  function clamp(value,min,max){return Math.max(min,Math.min(max,value));}
  function formatCompactNumber(value,smallDecimals=0){
    const number=Number(value)||0,absolute=Math.abs(number);if(absolute<1000)return smallDecimals?number.toFixed(smallDecimals):Math.round(number).toLocaleString();
    const suffixes=["k","m","b","t","q","Q","s","S"];let tier=Math.min(suffixes.length,Math.floor(Math.log10(absolute)/3)),scaled=number/Math.pow(1000,tier);if(Math.abs(scaled)>=999.5&&tier<suffixes.length){tier+=1;scaled=number/Math.pow(1000,tier);}const digits=Math.abs(scaled)>=100?0:Math.abs(scaled)>=10?1:2;
    const rendered=digits?scaled.toFixed(digits).replace(/\.?0+$/,""):Math.round(scaled).toString();return `${rendered}${suffixes[tier-1]}`;
  }
  function makeWaveStats(wave,seed={}){return {wave:Math.max(1,Math.floor(Number(wave)||1)),damage:{...(seed.damage||{})},healing:{...(seed.healing||{})},combatTime:Math.max(0,Number(seed.combatTime)||0),completed:!!seed.completed};}
  function normalizeStats(saved,currentWave){const source=saved||{},waves={};for(const [key,value] of Object.entries(source.waves||{})){const wave=Math.max(1,Math.floor(Number(value?.wave)||Number(key)||0));if(wave)waves[wave]=makeWaveStats(wave,value);}const activeWave=Math.max(0,Math.floor(Number(currentWave)||0));if(activeWave&&!waves[activeWave])waves[activeWave]=makeWaveStats(activeWave);const requested=Math.floor(Number(source.selectedWave)||0),selectedWave=waves[requested]?requested:activeWave||Math.max(0,...Object.keys(waves).map(Number));return {damage:{...(source.damage||{})},healing:{...(source.healing||{})},waves,selectedWave,waveOptionsSignature:"",peakDps:Math.max(0,Number(source.peakDps)||0)};}
  function ensureWaveStats(wave=state.wave){const id=Math.max(1,Math.floor(Number(wave)||1));state.stats.waves||={};return state.stats.waves[id]||(state.stats.waves[id]=makeWaveStats(id));}
