  function applySettings(){const scale=clamp(Number(state.settings.fontScale)||DEFAULT_SETTINGS.fontScale,100,160);state.settings.fontScale=scale;state.settings.panelPause=state.settings.panelPause===true;state.settings.draftPause=state.settings.draftPause!==false;if(!["sequential","random"].includes(state.settings.musicMode))state.settings.musicMode="sequential";if(!["celestial","tactical"].includes(state.settings.enemyStyle))state.settings.enemyStyle="celestial";if(!["simple","detail"].includes(state.settings.meterMode))state.settings.meterMode="simple";if(!CARD_PREFERENCES.some((item)=>item.id===state.settings.cardPreference))state.settings.cardPreference="";if(!DIFFICULTY_MAJORS.some((item)=>item.id===state.settings.difficultyMajor))state.settings.difficultyMajor="cruise";state.settings.difficultyMinor=clamp(Math.floor(Number(state.settings.difficultyMinor)||1),1,5);refreshDifficultyOptions();document.documentElement.style.setProperty("--ui-font-scale",String(scale/100));if($("#fontScaleInput"))$("#fontScaleInput").value=scale;if($("#fontScaleValue"))$("#fontScaleValue").textContent=`${scale}%`;if($("#panelPauseInput"))$("#panelPauseInput").checked=state.settings.panelPause;if($("#draftPauseInput"))$("#draftPauseInput").checked=state.settings.draftPause;if($("#musicModeInput"))$("#musicModeInput").value=state.settings.musicMode;if($("#enemyStyleInput"))$("#enemyStyleInput").value=state.settings.enemyStyle;if($("#difficultyMajorInput"))$("#difficultyMajorInput").value=state.settings.difficultyMajor;if($("#difficultyMinorInput"))$("#difficultyMinorInput").value=String(state.settings.difficultyMinor);if($("#difficultySummary")){const factors=difficultyFactors();$("#difficultySummary").textContent=`${difficultyName()} · 敌军生命 ×${factors.hp.toFixed(2)} · 攻击 ×${factors.attack.toFixed(2)} · 数量 ×${factors.count.toFixed(2)}`;}$$('input[name="cardPreference"]').forEach((radio)=>{radio.checked=radio.value===state.settings.cardPreference;});$$('[data-meter-mode]').forEach((button)=>button.classList.toggle("active",button.dataset.meterMode===state.settings.meterMode));const preference=CARD_PREFERENCES.find((item)=>item.id===state.settings.cardPreference);if($("#preferenceStatus"))$("#preferenceStatus").textContent=preference?`偏好：${preference.name}`:"未选择";updateTrackLabel();}
