  function loadAccountStore(){try{const saved=JSON.parse(localStorage.getItem(ACCOUNT_KEY));if(saved&&Array.isArray(saved.accounts))return {currentId:saved.currentId||null,accounts:saved.accounts};}catch{/* clean archive */}return {currentId:null,accounts:[]};}
