  async function ensureTestAccount(){let account=state.accountStore.accounts.find((item)=>item.id===TEST_ACCOUNT_ID);if(!account){account={id:TEST_ACCOUNT_ID,name:TEST_ACCOUNT_NAME,createdAt:Date.now(),lastLoginAt:0,best:{wave:25,score:0},progress:{maxClearedWave:25,totalBountyRewards:0},run:null,isTest:true};state.accountStore.accounts.push(account);}account.name=TEST_ACCOUNT_NAME;account.isTest=true;account.pinHash=await hashPin("1111",account.id);account.best||={wave:25,score:0};const progress=ensureProgress(account);progress.maxClearedWave=Math.max(25,progress.maxClearedWave||0);progress.difficultyClears=Object.fromEntries(DIFFICULTY_MAJORS.map((item)=>[item.id,5]));for(const relic of RELICS){if(!progress.unlockedRelics.includes(relic.id))progress.unlockedRelics.push(relic.id);progress.relicLevels[relic.id]=2;}persistAccountStore();}
  function validRun(run){return run?.version===SAVE_VERSION;}
  function renderProfiles(){const accounts=state.accountStore.accounts;$("#profileList").innerHTML=accounts.length?accounts.map((account)=>{const selected=account.id===state.pendingAccountId;const last=account.id===state.accountStore.currentId;const run=validRun(account.run)?`存档：第 ${account.run.wave} 波 · ${formatTime(account.run.elapsed||0)}`:account.run?"旧版记录需重新开始":"暂无进行中存档";return `<button class="profile-option ${selected?"active":""}" data-account="${account.id}" type="button"><i>${escapeHtml(account.name.slice(0,1).toUpperCase())}</i><span><b>${escapeHtml(account.name)}</b><small>${run}</small></span><em>${last?"上次登录":"选择"}</em></button>`;}).join(""):'<div class="profile-empty">这台设备还没有账号，请创建指挥官。</div>';$$('.profile-option').forEach((button)=>button.addEventListener("click",()=>selectAccount(button.dataset.account)));$("#loginArea").classList.toggle("hidden",!state.pendingAccountId);}
