  function waveScenario(wave){
    if(wave===1)return {id:"tutorial_swarm",name:"教学波次 · 小行星侦察",special:false,countScale:1,spawnScale:1.12,pool:["swarm","swarm","swarm"],hint:"熟悉基础射击与五段屏障"};
    if(wave===2)return {id:"tutorial_runner",name:"教学波次 · 彗星试探",special:false,countScale:1,spawnScale:1.04,pool:["swarm","swarm","runner"],hint:"首次出现高速目标"};
    if(wave===3)return {id:"tutorial_split",name:"教学波次 · 裂殖样本",special:false,countScale:1,spawnScale:1,pool:["swarm","runner","splitter"],hint:"裂殖目标会产生可攻击子体"};
    if(wave===4)return {id:"tutorial_armor",name:"教学波次 · 装甲编队",special:false,countScale:1,spawnScale:.96,pool:["swarm","runner","tank","frigate"],hint:"首次出现厚甲与属性克制"};
    if(wave%5===0)return SPECIAL_WAVE_SCENARIOS.speed;
    if(wave%5===2)return SPECIAL_WAVE_SCENARIOS.split;
    if(wave%5===4)return SPECIAL_WAVE_SCENARIOS.armor;
    return {id:"mixed",name:"深空混合潮",special:false,countScale:1,spawnScale:1,pool:null,hint:"多类型敌军混合推进"};
  }
  function normalEnemyPool(wave=state.wave){const pool=["swarm","swarm","runner"];if(wave>=3)pool.push("splitter");if(wave>=4)pool.push("tank","frigate");if(wave>=6)pool.push("shield","prism");if(wave>=8)pool.push("shooter","carrier");if(wave>=9)pool.push("splitter");if(wave>=10)pool.push("nova","frigate","prism","healer");if(wave>=13)pool.push("healer");if(wave>=15)pool.push("chorus");if(wave>=20)pool.push("chorus","healer");return pool;}
  function waveTargetCount(wave){const scenario=waveScenario(wave),early=BalanceCore.earlyWaveProfile(wave),base=(20+wave*3.4+Math.pow(wave,1.1)*1.25)*difficultyFactors().count*early.countScale*scenario.countScale;return Math.max(20+wave*2,Math.floor(base));}
  function subwaveCountForWave(wave){return Math.min(8,3+Math.floor(Math.max(0,wave-1)/4));}
  function subwaveSizeForWave(wave,target=state.waveBaseTarget||state.waveTarget){return Math.max(1,Math.ceil(target/subwaveCountForWave(wave)));}
  function interwaveFillerSlots(wave,target=state.waveBaseTarget||state.waveTarget){return Math.min(3,Math.max(2,Math.floor(subwaveSizeForWave(wave,target)*.22)));}
  function isInterwaveFillerSlot(wave,spawned,target=state.waveBaseTarget||state.waveTarget){const size=subwaveSizeForWave(wave,target),slot=Math.max(0,(spawned-1)%size);return slot>=Math.max(1,size-interwaveFillerSlots(wave,target));}
