  function spawnCadenceForWave(wave,spawned,target=state.waveBaseTarget||state.waveTarget,scenario=state.waveScenario||waveScenario(wave)){const size=subwaveSizeForWave(wave,target),slot=Math.max(0,(spawned-1)%size),lastInSubwave=slot===size-1;if(lastInSubwave)return subwaveRestDuration(wave,scenario);if(isInterwaveFillerSlot(wave,spawned,target))return Math.max(.82,1.32-wave*.012)*scenario.spawnScale;return Math.max(.34,.88-wave*.012)*scenario.spawnScale;}
  function subwaveIndexForSpawn(wave,spawned,target=state.waveBaseTarget||state.waveTarget){return Math.min(subwaveCountForWave(wave),Math.floor(Math.max(0,spawned)/subwaveSizeForWave(wave,target))+1);}
  function fastStartInfo(){const cleared=ensureProgress().maxClearedWave||0,startWave=Math.max(1,cleared-5),skipped=Math.max(0,startWave-1),rewardAppearances=Math.max(0,startWave-3),milestoneBonus=Math.floor(skipped/5);return {cleared,startWave,drafts:skipped+rewardAppearances+NEW_RUN_OPENING_DRAFTS+milestoneBonus};}
  function recordClearedWave(){const account=activeAccount();if(!account)return false;const progress=ensureProgress(account);if(state.wave>progress.maxClearedWave)progress.maxClearedWave=state.wave;evaluateAchievements(false);persistAccountStore();if(Number.isFinite(state.collectionCompleteWave)&&state.wave>=state.collectionCompleteWave+5){endGame(true);return true;}return false;}
