  function drawRepairBots(){for(const bot of state.repairBots||[]){const flying=bot.age<bot.flight,t=flying?clamp(bot.age/bot.flight,0,1):1,eased=t*t*(3-2*t),one=1-eased,x=flying?one*one*bot.startX+2*one*eased*bot.controlX+eased*eased*bot.targetX:bot.targetX,y=flying?one*one*bot.startY+2*one*eased*bot.controlY+eased*eased*bot.targetY:bot.targetY,arcAngle=bot.targetKind==="mini"?0:Math.atan2(bot.targetY-BARRIER_ARC.cy,bot.targetX-BARRIER_ARC.cx)+Math.PI/2;if(state.supportSkillTime>0){const turret=state.turrets.support,pulse=.65+.35*Math.sin(state.elapsed*15+bot.id);ctx.save();ctx.globalCompositeOperation="lighter";ctx.globalAlpha=.28+.38*pulse;ctx.strokeStyle="#baffec";ctx.shadowColor=COLORS.support;ctx.shadowBlur=16;ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(turret.x,turret.y-22);ctx.quadraticCurveTo((turret.x+x)/2,y-50-Math.sin(bot.id)*24,x,y);ctx.stroke();ctx.restore();}ctx.save();ctx.translate(x,y);ctx.rotate(flying?Math.atan2(bot.targetY-y,bot.targetX-x)+Math.PI/2:arcAngle);ctx.shadowColor=COLORS.support;ctx.shadowBlur=flying?12:18;ctx.fillStyle="rgba(6,29,31,.96)";ctx.strokeStyle=state.supportSkillTime>0?"#eafff6":COLORS.support;ctx.lineWidth=state.supportSkillTime>0?2.2:1.4;tracePolygon(6,7,Math.PI/6);ctx.fill();ctx.stroke();ctx.fillStyle="#dffff5";ctx.fillRect(-2.5,-2.5,5,5);ctx.strokeStyle=bot.shield>0?COLORS.gold:COLORS.cyan;ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(-6,1);ctx.lineTo(-10,6);ctx.moveTo(6,1);ctx.lineTo(10,6);ctx.stroke();if(!flying){const pulse=.55+.45*Math.sin(state.elapsed*12+bot.id);ctx.globalAlpha=pulse;ctx.strokeStyle=bot.shield>0?COLORS.gold:COLORS.support;ctx.beginPath();ctx.moveTo(-4,7);ctx.lineTo(-7,13);ctx.moveTo(4,7);ctx.lineTo(7,13);ctx.stroke();ctx.globalAlpha=.18+.16*pulse;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-12,12);ctx.lineTo(12,12);ctx.stroke();}ctx.restore();}}
