  const backgroundMusic=$("#backgroundMusic");
  let audioContext=null;
  function updateTrackLabel(){const track=MUSIC_TRACKS[state.musicIndex]||MUSIC_TRACKS[0];if($("#currentTrackName"))$("#currentTrackName").textContent=`当前：${track.title}`;if($("#musicButton"))$("#musicButton").title=`背景音乐：${track.title}`;}
  function loadMusicTrack(index,autoplay=true){state.musicIndex=(index+MUSIC_TRACKS.length)%MUSIC_TRACKS.length;const track=MUSIC_TRACKS[state.musicIndex];if(!backgroundMusic.src.endsWith(track.src))backgroundMusic.src=track.src;updateTrackLabel();if(autoplay)startBackgroundMusic();}
  function nextMusicTrack(){let next=(state.musicIndex+1)%MUSIC_TRACKS.length;if(state.settings.musicMode==="random"&&MUSIC_TRACKS.length>1){do{next=Math.floor(Math.random()*MUSIC_TRACKS.length);}while(next===state.musicIndex);}loadMusicTrack(next,true);}
  function syncBackgroundVolume(){
    backgroundMusic.volume = state.music
      ? (state.paused || state.drafting || !state.started ? .18 : .32)
      : 0;
  }
  function startBackgroundMusic(){if(!state.music)return;if(!backgroundMusic.getAttribute("src"))loadMusicTrack(state.musicIndex,false);syncBackgroundVolume();const promise=backgroundMusic.play();if(promise?.catch)promise.catch(()=>{/* wait for the next user gesture */});}
  function stopBackgroundMusic(){backgroundMusic.pause();}
  function playSound(kind){if(!state.sound)return;try{audioContext||=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==="suspended")audioContext.resume();const now=audioContext.currentTime,osc=audioContext.createOscillator(),gain=audioContext.createGain(),preset={shot:[520,.025,"square"],card:[620,.18,"triangle"],combo:[330,.35,"sine"],wave:[440,.24,"triangle"],start:[220,.35,"sine"],damage:[120,.15,"sawtooth"],end:[110,.5,"triangle"]}[kind]||[380,.06,"sine"];osc.type=preset[2];osc.frequency.setValueAtTime(preset[0],now);osc.frequency.exponentialRampToValueAtTime(Math.max(60,preset[0]*1.3),now+preset[1]);gain.gain.setValueAtTime(kind === "shot" ? .018 : .035, now);gain.gain.exponentialRampToValueAtTime(.0001,now+preset[1]);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+preset[1]);}catch{/* optional */}}
  function syncPauseUI(){$("#pauseIcon").textContent=state.paused?"▶":"Ⅱ";$("#pauseButton").classList.toggle("active",state.paused);$("#pauseVeil").classList.toggle("hidden",!state.paused||state.drafting||!state.started);syncBackgroundVolume();}
