  function resizeCanvas(){const dpr=Math.min(1.35,window.devicePixelRatio||1);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
  function updateQATelemetry(){
    const node=$("#qaPerf");if(!node)return;const perf=state.perf||(state.perf={frames:[],updateMs:[],drawMs:[],drawGaps:[],skillDispatchMs:0,jobBatchMs:0}),sorted=[...(perf.frames||[])].sort((a,b)=>a-b),pick=(ratio)=>sorted.length?sorted[Math.min(sorted.length-1,Math.floor(sorted.length*ratio))]:0,average=sorted.length?sorted.reduce((sum,value)=>sum+value,0)/sorted.length:0,summarize=(values)=>{const ordered=[...(values||[])].sort((a,b)=>a-b);return {average:ordered.length?ordered.reduce((sum,value)=>sum+value,0)/ordered.length:0,p95:ordered.length?ordered[Math.min(ordered.length-1,Math.floor(ordered.length*.95))]:0,max:ordered.at(-1)||0};},updateTiming=summarize(perf.updateMs),drawTiming=summarize(perf.drawMs),drawGapTiming=summarize(perf.drawGaps);
    const living=state.enemies.filter((enemy)=>!enemy.dead);node.dataset.frameAverage=average.toFixed(2);node.dataset.frameP95=pick(.95).toFixed(2);node.dataset.frameMax=(sorted.at(-1)||0).toFixed(2);node.dataset.skillDispatch=(perf.skillDispatchMs||0).toFixed(3);node.dataset.jobBatch=(perf.jobBatchMs||0).toFixed(3);node.dataset.enemies=String(living.length);node.dataset.bosses=String(living.filter((enemy)=>enemy.type.boss).length);node.dataset.frozen=String(living.filter(isEnemyFrozen).length);node.dataset.jobs=String((state.combatJobs||[]).length);node.dataset.wave=String(state.wave||0);
    node.dataset.updateAverage=updateTiming.average.toFixed(3);node.dataset.updateP95=updateTiming.p95.toFixed(3);node.dataset.updateMax=updateTiming.max.toFixed(3);node.dataset.drawAverage=drawTiming.average.toFixed(3);node.dataset.drawP95=drawTiming.p95.toFixed(3);node.dataset.drawMax=drawTiming.max.toFixed(3);node.dataset.drawGapAverage=drawGapTiming.average.toFixed(2);node.dataset.drawGapP95=drawGapTiming.p95.toFixed(2);node.dataset.drawGapMax=drawGapTiming.max.toFixed(2);node.dataset.invincible=state.qaInvincible?"1":"0";node.dataset.barrierHp=String(Math.round(state.globalBarrierHp));node.dataset.barrierMax=String(Math.round(state.globalBarrierMax));node.dataset.cardRanks=String([...state.cards.values()].reduce((sum,rank)=>sum+rank,0));node.dataset.miniTurrets=String(state.miniTurrets.filter((mini)=>!mini.dead).length);node.dataset.runners=String(living.filter((enemy)=>enemy.typeId==="runner").length);node.dataset.projectiles=String(state.projectiles.length);node.dataset.particles=String(state.particles.length);node.dataset.crowdLod=String(living.length>CROWD_LOD_HARD_LIMIT?2:living.length>CROWD_LOD_SOFT_LIMIT?1:0);
  }
  let uiAccumulator=0,statsAccumulator=0,lastDraw=0;
  function loop(time){const dt=state.lastTime?(time-state.lastTime)/1000:0;state.lastTime=time;state.perf=state.perf||{frames:[],updateMs:[],drawMs:[],drawGaps:[],skillDispatchMs:0,jobBatchMs:0};state.perf.updateMs||=[];state.perf.drawMs||=[];state.perf.drawGaps||=[];if(dt>0&&dt<.5){state.perf.frames.push(dt*1000);if(state.perf.frames.length>180)state.perf.frames.shift();}const updateStarted=performance.now();updateRealtimeEffects(time);update(dt*(state.gameSpeed===2?2:1));state.perf.updateMs.push(performance.now()-updateStarted);if(state.perf.updateMs.length>180)state.perf.updateMs.shift();uiAccumulator+=dt;statsAccumulator+=dt;if(uiAccumulator>.18){uiAccumulator=0;updateUI();}if(statsAccumulator>.2){statsAccumulator=0;updateStatsUI();updateQATelemetry();}const active=state.started&&!state.paused&&!state.gameOver,shouldDraw=active||time-lastDraw>=1000/18;if(shouldDraw){if(lastDraw>0){state.perf.drawGaps.push(time-lastDraw);if(state.perf.drawGaps.length>180)state.perf.drawGaps.shift();}lastDraw=time;const drawStarted=performance.now();draw(time);state.perf.drawMs.push(performance.now()-drawStarted);if(state.perf.drawMs.length>180)state.perf.drawMs.shift();}requestAnimationFrame(loop);}
  async function init(){await ensureTestAccount();state.turrets=makeTurrets();resizeCanvas();bindEvents();$("#relicButton").addEventListener("click",()=>openPanel("relicOverlay",renderRelicArchive));applySettings();loadMusicTrack(0,false);renderProfiles();updateAllUI();$("#startOverlay").classList.remove("show");openAccountPanel(true);draw(0);requestAnimationFrame(loop);}
